package com.example.gig_service.controller;

import com.example.gig_service.dto.*;
import com.example.gig_service.service.GigService;
import com.example.gig_service.service.ImageService;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;

import java.util.*;

@RestController
@RequestMapping("/api/gigs")
public class GigController {

    @Autowired
    private GigService gigService;

    @Autowired
    private ImageService imageService;

    @PostMapping
    public GigResponseDTO createGig(@RequestBody GigRequestDTO gigRequestDTO) {
        return gigService.createGig(gigRequestDTO);
    }

    @GetMapping
    public List<GigResponseDTO> getAllGigs() {
        return gigService.getAllGigs();
    }

        } catch (Exception e) {
            return ResponseEntity.badRequest().build();
        }
    }

    @PostMapping("/upload-image")
    public ResponseEntity<Map<String, String>> uploadImage(@RequestParam("file") MultipartFile file) {
        try {
            String imageUrl = imageService.uploadImage(file);
            Map<String, String> response = new HashMap<>();
            response.put("imageUrl", imageUrl);
            response.put("message", "Image uploaded successfully");
            return ResponseEntity.ok(response);
        } catch (Exception e) {
            Map<String, String> errorResponse = new HashMap<>();
            errorResponse.put("error", "Failed to upload image: " + e.getMessage());
            return ResponseEntity.badRequest().body(errorResponse);
        }
    }

    @PostMapping("/upload-images")
    public ResponseEntity<Map<String, Object>> uploadImages(@RequestParam("files") MultipartFile[] files) {
        try {
            if (files.length == 0) {
                Map<String, Object> errorResponse = new HashMap<>();
                errorResponse.put("error", "No files provided");
                return ResponseEntity.badRequest().body(errorResponse);
            }

            List<String> imageUrls = imageService.uploadMultipleImages(files);
            Map<String, Object> response = new HashMap<>();
            response.put("imageUrls", imageUrls);
            response.put("message", "Images uploaded successfully");
            response.put("count", imageUrls.size());
            return ResponseEntity.ok(response);
        } catch (Exception e) {
            Map<String, Object> errorResponse = new HashMap<>();
            errorResponse.put("error", "Failed to upload images: " + e.getMessage());
            return ResponseEntity.badRequest().body(errorResponse);
        }
    }

    /**
     * Get gig and specific package details by gigId and packageId
     * Verifies that both gig and package exist and that the package belongs to the gig
     */
    @GetMapping("/{gigId}/packages/{packageId}")
    public ResponseEntity<GigWithPackageDetailsDTO> getGigWithPackageDetails(
            @PathVariable UUID gigId,
            @PathVariable UUID packageId) {
        try {
            GigWithPackageDetailsDTO response = gigService.getGigWithPackageDetails(gigId, packageId);
            return ResponseEntity.ok(response);
        } catch (NoSuchElementException e) {
            return ResponseEntity.notFound().build();
        }
    }

    /**
     * Verify if a gig and package combination exists
     */
    @GetMapping("/{gigId}/packages/{packageId}/verify")
    public ResponseEntity<Map<String, Boolean>> verifyGigAndPackageExists(
            @PathVariable UUID gigId,
            @PathVariable UUID packageId) {
        boolean exists = gigService.verifyGigAndPackageExists(gigId, packageId);
        Map<String, Boolean> response = new HashMap<>();
        response.put("exists", exists);
        return ResponseEntity.ok(response);
    }

    /**
     * Get all packages for a specific gig
     */
    @GetMapping("/{gigId}/packages")
    public ResponseEntity<List<GigPackageDetailsDTO>> getPackagesByGigId(@PathVariable UUID gigId) {
        try {
            List<GigPackageDetailsDTO> packages = gigService.getPackagesByGigId(gigId);
            return ResponseEntity.ok(packages);
        } catch (NoSuchElementException e) {
            return ResponseEntity.notFound().build();
        }
    }
}

package com.example.gig_service.controller;

import com.example.gig_service.dto.*;
import com.example.gig_service.service.GigService;
import com.example.gig_service.service.ImageService;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;

import java.util.*;

@RestController
@RequestMapping("/api/gigs")
public class GigController {

    @Autowired
    private GigService gigService;

    @Autowired
    private ImageService imageService;

    @PostMapping
    public GigResponseDTO createGig(@RequestBody GigRequestDTO gigRequestDTO) {
        return gigService.createGig(gigRequestDTO);
    }

    @GetMapping
    public List<GigResponseDTO> getAllGigs() {
        return gigService.getAllGigs();
    }

    @GetMapping("/seller/{sellerId}")
    public List<GigResponseDTO> getGigsBySellerId(@PathVariable UUID sellerId) {
        return gigService.getGigsBySellerId(sellerId);
    }

    @PatchMapping("/{id}/status")
    public GigResponseDTO updateGigStatus(@PathVariable UUID id, @RequestBody UpdateGigStatusRequest request) {
        return gigService.updateGigStatus(id, request.getStatus());
    }

    @GetMapping("/{id}")
    public GigResponseDTO getGigById(@PathVariable UUID id) {
        return gigService.getGigById(id);
    }

    @PutMapping("/{id}")
    public GigResponseDTO updateGig(@PathVariable UUID id, @RequestBody GigRequestDTO gigRequestDTO) {
        return gigService.updateGig(id, gigRequestDTO);
    }

    @DeleteMapping("/{id}")
    public void deleteGig(@PathVariable UUID id) {
        gigService.deleteGig(id);
    }

    @PostMapping("/create-with-images")
    public ResponseEntity<GigResponseDTO> createGigWithImages(
            @RequestParam("sellerId") UUID sellerId,
            @RequestParam("title") String title,
            @RequestParam("description") String description,
            @RequestParam("platform") String platform,
            @RequestParam("category") String category,
            @RequestParam("status") String status,
            @RequestParam(value = "images", required = false) MultipartFile[] imageFiles,
            @RequestParam(value = "primaryImageIndex", required = false, defaultValue = "0") int primaryImageIndex,
            @RequestParam(value = "packages", required = false) String packagesJson,
            @RequestParam(value = "faqs", required = false) String faqsJson) {

        try {
            GigRequestDTO gigRequestDTO = new GigRequestDTO();
            gigRequestDTO.setSellerId(sellerId);
            gigRequestDTO.setTitle(title);
            gigRequestDTO.setDescription(description);
            gigRequestDTO.setPlatform(platform);
            gigRequestDTO.setCategory(category);
            gigRequestDTO.setStatus(status);

            // Handle image uploads
            if (imageFiles != null && imageFiles.length > 0) {
                List<String> imageUrls = imageService.uploadMultipleImages(imageFiles);
                List<GigImageDTO> imageDTOs = new ArrayList<>();

                for (int i = 0; i < imageUrls.size(); i++) {
                    GigImageDTO imageDTO = new GigImageDTO();
                    imageDTO.setUrl(imageUrls.get(i));
                    imageDTO.setIsPrimary(i == primaryImageIndex);
                    imageDTOs.add(imageDTO);
                }
                gigRequestDTO.setImages(imageDTOs);
            }

            // Handle packages JSON
            if (packagesJson != null && !packagesJson.trim().isEmpty()) {
                ObjectMapper mapper = new ObjectMapper();
                List<GigPackageDTO> packages = mapper.readValue(packagesJson,
                    new TypeReference<List<GigPackageDTO>>() {});
                gigRequestDTO.setPackages(packages);
            }

            // Handle FAQs JSON
            if (faqsJson != null && !faqsJson.trim().isEmpty()) {
                ObjectMapper mapper = new ObjectMapper();
                List<GigFaqDTO> faqs = mapper.readValue(faqsJson,
                    new TypeReference<List<GigFaqDTO>>() {});
                gigRequestDTO.setFaqs(faqs);
            }

            GigResponseDTO response = gigService.createGig(gigRequestDTO);
            return ResponseEntity.ok(response);

        } catch (Exception e) {
            return ResponseEntity.badRequest().build();
        }
    }

    @PostMapping("/upload-image")
    public ResponseEntity<Map<String, String>> uploadImage(@RequestParam("file") MultipartFile file) {
        try {
            String imageUrl = imageService.uploadImage(file);
            Map<String, String> response = new HashMap<>();
            response.put("imageUrl", imageUrl);
            response.put("message", "Image uploaded successfully");
            return ResponseEntity.ok(response);
        } catch (Exception e) {
            Map<String, String> errorResponse = new HashMap<>();
            errorResponse.put("error", "Failed to upload image: " + e.getMessage());
            return ResponseEntity.badRequest().body(errorResponse);
        }
    }

    @PostMapping("/upload-images")
    public ResponseEntity<Map<String, Object>> uploadImages(@RequestParam("files") MultipartFile[] files) {
        try {
            if (files.length == 0) {
                Map<String, Object> errorResponse = new HashMap<>();
                errorResponse.put("error", "No files provided");
                return ResponseEntity.badRequest().body(errorResponse);
            }

            List<String> imageUrls = imageService.uploadMultipleImages(files);
            Map<String, Object> response = new HashMap<>();
            response.put("imageUrls", imageUrls);
            response.put("message", "Images uploaded successfully");
            response.put("count", imageUrls.size());
            return ResponseEntity.ok(response);
        } catch (Exception e) {
            Map<String, Object> errorResponse = new HashMap<>();
            errorResponse.put("error", "Failed to upload images: " + e.getMessage());
            return ResponseEntity.badRequest().body(errorResponse);
        }
    }

    /**
     * Get gig and specific package details by gigId and packageId
     * Verifies that both gig and package exist and that the package belongs to the gig
     */
    @GetMapping("/{gigId}/packages/{packageId}")
    public ResponseEntity<GigWithPackageDetailsDTO> getGigWithPackageDetails(
            @PathVariable UUID gigId,
            @PathVariable UUID packageId) {
        try {
            GigWithPackageDetailsDTO response = gigService.getGigWithPackageDetails(gigId, packageId);
            return ResponseEntity.ok(response);
        } catch (NoSuchElementException e) {
            return ResponseEntity.notFound().build();
        }
    }

    /**
     * Verify if a gig and package combination exists
     */
    @GetMapping("/{gigId}/packages/{packageId}/verify")
    public ResponseEntity<Map<String, Boolean>> verifyGigAndPackageExists(
            @PathVariable UUID gigId,
            @PathVariable UUID packageId) {
        boolean exists = gigService.verifyGigAndPackageExists(gigId, packageId);
        Map<String, Boolean> response = new HashMap<>();
        response.put("exists", exists);
        return ResponseEntity.ok(response);
    }

    /**
     * Get all packages for a specific gig
     */
    @GetMapping("/{gigId}/packages")
    public ResponseEntity<List<GigPackageDetailsDTO>> getPackagesByGigId(@PathVariable UUID gigId) {
        try {
            List<GigPackageDetailsDTO> packages = gigService.getPackagesByGigId(gigId);
            return ResponseEntity.ok(packages);
        } catch (NoSuchElementException e) {
            return ResponseEntity.notFound().build();
        }
    }

    /**
     * Handle review notification from order service to update gig rating statistics
     */
    @PostMapping("/{gigId}/reviews")
    public ResponseEntity<Map<String, String>> handleReviewNotification(
            @PathVariable UUID gigId,
            @RequestBody Map<String, Object> reviewData) {
        try {
            Integer rating = (Integer) reviewData.get("rating");
            String reviewText = (String) reviewData.get("reviewText");

            // Handle UUID conversion more safely
            Object reviewerIdObj = reviewData.get("reviewerId");
            UUID reviewerId;
            if (reviewerIdObj instanceof String) {
                reviewerId = UUID.fromString((String) reviewerIdObj);
            } else {
                reviewerId = (UUID) reviewerIdObj;
            }

            String createdAt = (String) reviewData.get("createdAt");

            // Call service to update gig rating statistics
            gigService.updateGigRatingFromReview(gigId, rating);

            Map<String, String> response = new HashMap<>();
            response.put("status", "success");
            response.put("message", "Review notification processed successfully");
            return ResponseEntity.ok(response);
        } catch (Exception e) {
            Map<String, String> errorResponse = new HashMap<>();
            errorResponse.put("status", "error");
            errorResponse.put("message", "Failed to process review notification: " + e.getMessage());
            return ResponseEntity.badRequest().body(errorResponse);
        }
    }

    /**
     * Admin endpoint to manually set gig rating - useful for fixing existing data
     */
    @PostMapping("/{gigId}/admin/set-rating")
    public ResponseEntity<Map<String, String>> setGigRating(
            @PathVariable UUID gigId,
            @RequestParam Double averageRating,
            @RequestParam Integer totalReviews) {
        try {
            gigService.setGigRating(gigId, averageRating, totalReviews);

            Map<String, String> response = new HashMap<>();
            response.put("status", "success");
            response.put("message", "Gig rating updated successfully");
            return ResponseEntity.ok(response);
        } catch (Exception e) {
            Map<String, String> errorResponse = new HashMap<>();
            errorResponse.put("status", "error");
            errorResponse.put("message", "Failed to update gig rating: " + e.getMessage());
            return ResponseEntity.badRequest().body(errorResponse);
        }
    }
}

